      "contents": "use std::os::raw::c_float;

#[unsafe(no_mangle)]
pub extern "C" fn rgb_to_hsv(dest: *mut c_float, src: *const c_float) {
    unsafe {
        let r = *src.add(0);
        let g = *src.add(1);
        let b = *src.add(2);
        let mut h: c_float = 0.0;
        let mut s: c_float = 0.0;
        let v: c_float;
        let mut min = r;
        let mut max = r;
        min = if min < g { min } else { g };
        min = if min < b { min } else { b };
        max = if max > g { max } else { g };
        max = if max > b { max } else { b };
        let delta = max - min;
        v = max;
        if delta == 0.0 || max == 0.0 {
            *dest.add(0) = h;
            *dest.add(1) = s;
            *dest.add(2) = v;
            return;
        }
        s = delta / max;
        if r == max {
            h = (g - b) / delta;
        } else if g == max {
            h = 2.0 + (b - r) / delta;
        } else {
            h = 4.0 + (r - g) / delta;
        }
        h *= 60.0;
        if h < 0.0 {
            h += 360.0;
        }
        *dest.add(0) = h;
        *dest.add(1) = s;
        *dest.add(2) = v;
    }
}
